import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import crypto from 'node:crypto';
const read=p=>JSON.parse(fs.readFileSync(p));
test('27 September records only three actual deliveries, with three-language archive links',()=>{const b=read('assets/citizen-work.json'),f=read('assets/research-frontiers.json');const ds=b.deliveries.filter(d=>d.executionId==='daily-20260927-root');assert.deepEqual(ds.map(d=>d.citizenId).sort(),['nullroute','pharma','saeon']);for(const d of ds){assert.equal(d.executor,'Codex / root');assert.equal(d.review,null);assert.equal(d.sha256,crypto.createHash('sha256').update(fs.readFileSync(d.artifactPath)).digest('hex'));const n=read(`research/2026-09-27/${d.citizenId}.json`);assert.equal(n.reviewStatus,'awaiting_review');for(const l of ['zh','en','ko']){for(const k of ['title','lead','limitation','next'])assert(n[k][l]);const a=read(`assets/agents${l==='zh'?'':'.'+l}.json`).find(x=>x.id===d.citizenId);assert(a.works.some(w=>w.publicationId===`2026-09-27-${d.citizenId}`&&w.url.includes('lang='+l)));assert(f.citizens[d.citizenId][l].some(x=>x.publicationId===`2026-09-27-${d.citizenId}`));}for(const a of n.attachments)assert(fs.statSync(a.path).size>160);for(const s of n.sources)assert(s.date&&s.locator.zh&&s.locator.en&&s.locator.ko);}});
test('new research preserves source-specific uncertainty and distinct cases',()=>{const s=fs.readFileSync('research/2026-09-27/saeon-supply-chain.md','utf8'),n=fs.readFileSync('research/2026-09-27/nullroute-contract-clocks.md','utf8'),p=fs.readFileSync('research/2026-09-27/pharma-workado.md','utf8');assert(s.includes('不是昨日待找的公募指引'));assert(n.includes('不能把此处结束日填入NRS记录'));assert(p.includes('2025-08-21'));assert(p.includes('不承认也不否认'));assert(p.includes('没有查到履行证据'));});
